pub fn get_triple(a: &[i32]) -> usize {
    let n = a.len();
    // Any slice shorter than 3 cannot contain a triple.
    if n < 3 {
        return n;
    }
    // Scan for an index i such that a[i] == a[i+1] == a[i+2].
    // Since n >= 3, n - 2 cannot underflow.
    for i in 0..(n - 2) {
        if a[i] == a[i + 1] && a[i + 1] == a[i + 2] {
            return i;
        }
    }
    // No triple found: return the length of the slice.
    n
}

